import{_ as a,o as e,c as o,a3 as i}from"./chunks/framework.CVt6dz2a.js";const p=JSON.parse('{"title":"EP.08 灯光与阴影映射","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.08-light-shadow.md","filePath":"comics/EP.08-light-shadow.md","lastUpdated":1792595797000}'),d={name:"comics/EP.08-light-shadow.md"};function r(s,t,l,n,h,c){return e(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="ep-08-灯光与阴影映射" tabindex="-1">EP.08 灯光与阴影映射 <a class="header-anchor" href="#ep-08-灯光与阴影映射" aria-label="Permalink to &quot;EP.08 灯光与阴影映射&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/08-light/basics">8.1 基础入门：灯光与阴影</a> 延伸阅读：<a href="./../guide/08-light/advanced">进阶篇</a> · <a href="./../guide/08-light/practice">实战篇</a> 动手演示：<a href="./../public/demos/light/lights.html">lights 五种光源</a> · <a href="./../public/demos/light/shadow-basics.html">shadow-basics 阴影三杠杆</a> · <a href="./../public/demos/light/three-point.html">three-point 三点布光</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>标签君按老教程写 <code>new PointLight(0xffffff, 2)</code>，两米外的物体还是黑的——灯明明&quot;开了&quot;。</td></tr><tr><td>② 揭秘</td><td>码叔画出两遍渲染：阴影不是黑贴图，而是从<strong>光源视角</strong>先渲染一张深度图，再从相机视角逐像素比较深度；只有三种灯能投影。</td></tr><tr><td>③ 实证</td><td>像素酱调清三个杠杆（mapSize、收紧阴影相机、bias/normalBias），再摆出 Key/Fill/Rim 三点布光，产品质感直接拉满。</td></tr><tr><td>④ 结案</td><td>码叔总结：点光源 r155+ 走物理衰减，强度要几十到几百；阴影是昂贵的两遍渲染，预算省着花。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-物理光照-intensity-2-为什么看不见" tabindex="-1">① 物理光照：intensity=2 为什么看不见 <a class="header-anchor" href="#_1-物理光照-intensity-2-为什么看不见" aria-label="Permalink to &quot;① 物理光照：intensity=2 为什么看不见&quot;">​</a></h3><p>r155 起 WebGLRenderer 默认使用物理光照单位，<code>PointLight</code> / <code>SpotLight</code> 默认 <code>decay = 2</code>（平方反比衰减）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>表面到达亮度 ≈ intensity / distance²</span></span></code></pre></div><p>距离 2 米时 intensity=2 只剩 0.5，距离 5 米只剩 0.08。使用点光/聚光时强度通常要给<strong>几十到几百</strong>（并配合 <code>distance</code> 衰减半径）。Ambient/Hemisphere/Directional 不做距离衰减，仍是 0.x ~ 3 的小数值。</p><h3 id="_2-五种光源与投影能力" tabindex="-1">② 五种光源与投影能力 <a class="header-anchor" href="#_2-五种光源与投影能力" aria-label="Permalink to &quot;② 五种光源与投影能力&quot;">​</a></h3><table tabindex="0"><thead><tr><th>光源</th><th>类比</th><th>投影</th></tr></thead><tbody><tr><td>AmbientLight</td><td>均匀环境底光</td><td>❌</td></tr><tr><td>HemisphereLight</td><td>天空/地面两色半球光</td><td>❌</td></tr><tr><td>DirectionalLight</td><td>太阳（平行光）</td><td>✅</td></tr><tr><td>PointLight</td><td>灯泡（全方向）</td><td>✅（6 面深度图，成本最高）</td></tr><tr><td>SpotLight</td><td>聚光灯（锥形光束）</td><td>✅</td></tr></tbody></table><p>阴影三件套缺一不可：<code>renderer.shadowMap.enabled = true</code>、<code>light.castShadow = true</code>、<code>mesh.castShadow = true</code>（接收方还要 <code>receiveShadow = true</code>）。注意 <code>SpotLight.target</code> 是个 Object3D，<strong>必须 add 进场景</strong>，改变它的位置才生效。</p><h3 id="_3-阴影是两遍渲染" tabindex="-1">③ 阴影是两遍渲染 <a class="header-anchor" href="#_3-阴影是两遍渲染" aria-label="Permalink to &quot;③ 阴影是两遍渲染&quot;">​</a></h3><ol><li><strong>深度 Pass</strong>：从光源位置渲染一遍场景，只记录每个像素最近表面的深度（阴影图）；</li><li><strong>相机 Pass</strong>：正常渲染时，把每个像素投影回光源空间与深度图比较，被其他表面挡住的像素就在阴影里。</li></ol><p>默认 <code>PCFShadowMap</code> 提供柔和边缘，<code>VSMShadowMap</code> 更软但可能漏光。</p><h3 id="_4-清晰阴影三杠杆" tabindex="-1">④ 清晰阴影三杠杆 <a class="header-anchor" href="#_4-清晰阴影三杠杆" aria-label="Permalink to &quot;④ 清晰阴影三杠杆&quot;">​</a></h3><ol><li><code>light.shadow.mapSize.set(2048, 2048)</code>：深度图分辨率，越高越锐利，成本越高；</li><li><strong>收紧阴影相机</strong>：DirectionalLight 的阴影是正交相机，把 left/right/top/bottom/far 收到刚好包住场景，等效分辨率大幅提升；</li><li><strong>bias / normalBias</strong>：消除阴影痤疮（见坑点）。</li></ol><h3 id="_5-三点布光" tabindex="-1">⑤ 三点布光 <a class="header-anchor" href="#_5-三点布光" aria-label="Permalink to &quot;⑤ 三点布光&quot;">​</a></h3><ul><li><strong>Key 主光</strong>：暖色、强度最高（约 2.6），唯一开启投影，负责造型；</li><li><strong>Fill 补光</strong>：冷色、较弱（约 0.9），<strong>不投影</strong>，抬起暗部；</li><li><strong>Rim 轮廓光</strong>：放在主体后上方，勾出一圈亮边，把主体从背景分离。</li></ul><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：阴影表面全是条纹/麻点（shadow acne）？</strong> 平面为主调负 <code>shadow.bias</code>（如 -0.0005）；曲面为主调 <code>shadow.normalBias</code>（如 0.02），沿法线偏移深度采样。</li><li><strong>Q：物体看起来悬空、影子和脚分开（peter-panning）？</strong> bias/normalBias 调过头了，往回收。</li><li><strong>Q：多盏灯都开投影，影子互相矛盾且掉帧？</strong> 投影是昂贵的逐光源 Pass，通常只让一盏 Key 光投影，Fill/Rim 只负责照明。</li><li><strong>Q：SpotLight 照的方向不对？</strong> 忘了把 <code>spot.target</code> 加入场景树；它的位置更新后还需 <code>target.updateMatrixWorld()</code>（add 进树会自动）。</li></ul><h2 id="自测-quiz" tabindex="-1">自测（Quiz） <a class="header-anchor" href="#自测-quiz" aria-label="Permalink to &quot;自测（Quiz）&quot;">​</a></h2><ol><li>r155+ 物理光照下，PointLight intensity=2 在 4 米处到达亮度约为多少？为什么老教程数值不亮了？</li><li>哪三种灯可以投射阴影？其中哪种成本最高，为什么？</li><li>阴影痤疮在平面和曲面上分别优先调哪个参数？调过头会出现什么现象？</li></ol><details><summary>答案</summary><ol><li>约 <strong>2 / 4² = 0.125</strong>。默认 decay=2 平方反比衰减使老教程里&quot;1~2 强度&quot;的点光几乎无照明，新单位下点光/聚光强度需要<strong>几十到几百</strong>。</li><li><strong>DirectionalLight、SpotLight、PointLight</strong>；<strong>PointLight 成本最高</strong>——它需要渲染立方体贴图的 <strong>6 个面</strong>深度图。</li><li>平面优先 <strong><code>bias</code></strong>（小幅负值，如 -0.0005），曲面优先 <strong><code>normalBias</code></strong>（如 0.02）。调过头会导致 <strong>peter-panning：影子与物体分离、物体像悬空</strong>。</li></ol></details>',24)])])}const u=a(d,[["render",r]]);export{p as __pageData,u as default};
